#include "rpg/pve_visual.hpp"
#include "rpg/battle_presentation.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;using namespace rpg::presentation;
void check(bool ok,const char* why){if(!ok){throw std::runtime_error(why);}}
SequentialVisualDefinition quick(bool phases=true){auto d=sequential_lab_definition(phases);d.encounter.boss.max_health=1000000;for(auto& squad:d.encounter.squads){squad.rules.action_budget=ActionBudget{1,LimitOutcome::Draw};}return d;}
void drive(SequentialVisualSession& s){for(int i=0;i<220&&!s.finished();++i){const auto v=s.state();if(v.automatic){check(s.step_automatic().accepted(),"enemy action");}else{check(s.submit(v.revision,1,s.hud().boss_id).accepted(),"player action");}}check(s.finished(),"sequence bounded");}
void definition(){const auto d=sequential_lab_definition();check(d.encounter.squads.size()==3&&d.loadouts.size()==3&&d.encounter.squads[0].members[0].character_id=="FELIPE"&&d.encounter.squads[1].members[0].character_id=="A1"&&d.encounter.squads[2].members[0].character_id=="B1","three distinct identities");check(d.encounter.squads[2].members[0].fighter.team==Team::A&&terminal_lab_setup().roster[3].team==Team::B,"ally fixture does not change generic roster");}
void purity(){SequentialVisualSession s;const auto before=s.observation();for(int i=0;i<50;++i){static_cast<void>(s.state());static_cast<void>(s.hud());}check(s.observation()==before&&s.hud().squad_number==1&&s.hud().squad_count==3,"read only");}
void switch_team(){SequentialVisualSession s(quick());const auto hp=s.hud().boss_health;check(s.submit(0,1,"CHEFE-SEQ").accepted(),"first squad hit");const auto h=s.hud();check(h.squad_number==2&&h.local_actions==0&&h.global_actions==1&&h.boss_health<hp&&h.previous_squad=="equipe-1"&&h.next_squad=="equipe-3","transition counters and boss HP carry");check(s.state().combat.battle.current_actor=="A1"&&ability_card(s.state(),2).selectable,"new individual loadout");check(h.boss_phase=="SEQ-2"&&h.previous_phase=="SEQ-1","phase follows squad");}
void stale(){SequentialVisualSession s(quick());check(s.submit(0,1,"CHEFE-SEQ").accepted(),"transition");const auto before=s.observation();check(s.submit(0,1,"CHEFE-SEQ").error==VisualError::StaleCommand&&s.observation()==before,"old gesture rejected");check(!s.submit_action(1,{"FELIPE",ActionType::Attack,"CHEFE-SEQ"}).accepted()&&s.observation()==before,"old squad actor rejected");}
void exhausted(){SequentialVisualSession s(quick());drive(s);check(s.hud().squad_number==3&&s.hud().global_actions==3&&!s.hud().objective_met&&s.observation().end_reason==SequentialEndReason::SquadsExhausted,"one participation each, no cycling");check(s.submit(s.state().revision,1,"CHEFE-SEQ").error==VisualError::Finished,"no post-sequence input");}
void early_win(){auto d=sequential_lab_definition();d.encounter.boss.max_health=1;d.encounter.boss.stats.block=0;SequentialVisualSession s(d);check(s.submit(0,1,"CHEFE-SEQ").accepted()&&s.finished()&&s.hud().objective_met&&s.hud().squad_number==1&&!s.hud().next_squad,"boss defeat ends before other squads");check(s.state().progress.credits==0&&s.state().progress.completions.empty(),"no generic rewards");}
void fixed_kit(){SequentialVisualSession s(quick(false));check(s.hud().boss_phase=="stable","fixed initial kit");check(s.submit(0,1,"CHEFE-SEQ").accepted()&&s.hud().boss_phase=="stable"&&s.hud().previous_phase=="stable","no forced phase change");}
void changed_kit(){SequentialVisualSession s(quick());check(s.submit(0,1,"CHEFE-SEQ").accepted(),"second phase");auto v=s.state();const auto skill=std::ranges::find(v.combat.battle.rules.skills,std::string("CHEFE-SEQ-A1"),&SkillDefinition::id);check(skill!=v.combat.battle.rules.skills.end()&&skill->effects[0].power_ratio==12500,"stable ID, updated strength");check(s.submit(v.revision,1,"CHEFE-SEQ").accepted(),"third phase");v=s.state();const auto third=std::ranges::find(v.combat.battle.rules.skills,std::string("CHEFE-SEQ-A1"),&SkillDefinition::id);check(s.hud().boss_phase=="SEQ-3"&&third->effects[0].power_ratio==15000,"third phase strength");}
void core_equivalence(){auto d=quick();SequentialSquads core(d.encounter);SequentialVisualSession view(d);for(const auto& actor:{std::string("FELIPE"),std::string("A1"),std::string("B1")}){const auto v=view.state();const auto skill=v.abilities[0].slot.active_skill;check(core.apply({actor,ActionType::Skill,"CHEFE-SEQ",*skill}).action.accepted()&&view.submit(v.revision,1,"CHEFE-SEQ").accepted(),"matching action");check(core.battle().find("CHEFE-SEQ")->health==view.hud().boss_health&&core.snapshot().squad_index==view.observation().squad_index&&core.snapshot().accepted_actions==view.hud().global_actions,"core authoritative carry and scheduling");}}
void limit(){auto d=quick();d.encounter.global_budget=ActionBudget{1,LimitOutcome::Draw};SequentialVisualSession s(d);check(s.submit(0,1,"CHEFE-SEQ").accepted()&&s.finished()&&!s.hud().objective_met&&s.hud().squad_number==1&&s.hud().global_remaining==0&&s.observation().end_reason==SequentialEndReason::GlobalActionLimit,"global limit prevents next squad");}
void restart(){SequentialVisualSession s(quick());check(s.submit(0,1,"CHEFE-SEQ").accepted(),"second squad");s.abandon();const auto before=s.observation();check(s.submit(1,1,"CHEFE-SEQ").error==VisualError::SafetyStop&&s.observation()==before,"abandon inert");s.reset();check(s.hud().squad_number==1&&s.hud().boss_health==1000000&&!s.hud().previous_squad&&s.state().progress.attempt==2,"fresh sequence");}
void full_and_isolated(){VisualSession generic(terminal_lab_setup());PveVisualSession ritual;WaveVisualSession waves;const auto a=generic.state();const auto b=ritual.observation();const auto c=waves.observation();SequentialVisualSession fixed(sequential_lab_definition(false)),phased;drive(fixed);drive(phased);check(generic.state().combat==a.combat&&ritual.observation()==b&&waves.observation()==c,"all other labs isolated");}
void invalid(){auto d=sequential_lab_definition();d.loadouts.pop_back();bool caught=false;try{SequentialVisualSession bad(d);}catch(const std::invalid_argument&){caught=true;}check(caught,"catalog count rejected");}
int main(){try{definition();purity();switch_team();stale();exhausted();early_win();fixed_kit();changed_kit();core_equivalence();limit();restart();full_and_isolated();invalid();std::cout<<"REG_SEQ_VISUAL_TESTS_RESULT passed=13 total=13\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}